    while(শাৰী_স্থান_সলনি_কৰক>=행수-1){맨위=অন্ত_কৰক_অফছেট(맨위);if(맨위<দৈর্ঘ্য_মান)맨위++;শাৰী_স্থান_সলনি_কৰক--;}
